import puppeteer from "puppeteer";
import fs from "fs";
import { base64url } from "jose";

const generate = async ({ url, req, userListQuestions }) => {
    // console.log("User List questions", userListQuestions );
    // const logoB64 = fs.readFileSync('./src/public/images/logo-edk.png', {encoding:'base64'});
    // console.log(logoB64);
	
    const company = "Eduteka";

    var config = {
        headless: true,
        defaultViewport: {
            width: 750,
            height: 500,
            deviceScaleFactor: 1,
            isMobile: true,
            hasTouch: false,
            isLandscape: false
        }
    };

    if ( process.env.MODE == "PRODUCTION" ) {
        config['executablePath'] = '/usr/bin/chromium-browser';
        config['args'] = ["--no-sandbox"];
    }
    const browser = await puppeteer.launch(config);

    const page = await browser.newPage();
    await page.goto(url, {
        waitUntil: "networkidle0",
    });

    const cookies = [{
        name: 'session',
        value: req.cookies.session
    }];

    await page.setCookie(...cookies);
    const cookieSet = await page.cookies(url);

    console.log("cookies set", JSON.stringify(cookieSet));

    await page.emulateMediaType("screen");
    const pdf = await page.pdf({
        format: "A4",
        printBackground: true,
        headerTemplate: `
        '<table style="width:100%;margin-top: -10px; margin-left: 18px; margin-right: 18px; border-bottom-style: solid; border-bottom-color: black; border-bottom-width: 1px; " >
        <tr style="width: 100%;" >
            <td style="width:50%;color:#676666;" width="50%" >
            <span style="font-size:13px;">${userListQuestions.name}</span> </span> | <span style="font-size:15px;"><span style="font-weight:bold;"> | ${company}</span> 
            </td>
            <td style="width:45%;"></td>
            <td style="width:2%" style="text-align:end;" >
                <img src="data:image/png;base64," style="width:20px;"/>
            </td>
        </tr>
        </table> `,
        footerTemplate: `
        <table style="width:100%; margin-left: 18px;margin-bottom:-10px; margin-right: 18px; border-top-style: solid; border-top-color: black; border-top-width: 1px; " >
        <tr style="width: 100%;" >
            <td style="width:70%;color:#676666;" width="70%" >
            <span style="font-size:10px;"><span style="font-weight:bold;">Elaborado en <a href="${process.env.APP_URL}">${process.env.WEB_URL}</a></span> | <span class="date" style="font-size:10px;"></span> </span>
            </td>
            <td style="width:28%" style="text-align:end;"></td>
            <td style="width:2%" style="text-align:end;" >
            <span class="pageNumber" style="font-size:10px;" ></span><span style="font-size: 10px;"  >/</span><span class="totalPages" style="font-size:10px;" ></span>
            </td>
        </tr>
        </table>
        `,
        displayHeaderFooter: true,
        margin: {
            left: "0.5cm",
            top: "40px",
            right: "0.5cm",
            bottom: "40px"
        },
        // path: '.pdf'
    });
    await browser.close();
    return pdf;
}
export {generate}
